import { Link } from "react-router-dom";
import React, { useEffect, useState } from "react";
import PropTypes from "prop-types";
import { getAllCars, deleteCarById } from "../../services/ApiCar";
import moment from "moment";
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

export default function CardVoiture({ color = "light" }) {
  const [cars, setCars] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [carToDelete, setCarToDelete] = useState(null);

  // Fonctions de notification
  const notifySuccess = (message) => toast.success(message);
  const notifyError = (message) => toast.error(message);

  const fetchCars = async () => {
    try {
      setLoading(true);
      const response = await getAllCars();
      setCars(response.data);
    } catch (err) {
      setError("Erreur lors du chargement des voitures");
      notifyError("Erreur lors du chargement des données");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteClick = (id) => {
    setCarToDelete(id);
    setShowModal(true);
  };

  const confirmDelete = async () => {
    try {
      await deleteCarById(carToDelete);
      notifySuccess("Voiture supprimée avec succès !");
      fetchCars();
    } catch (err) {
      notifyError("Échec de la suppression de la voiture");
      console.error(err);
    } finally {
      setShowModal(false);
    }
  };

  useEffect(() => {
    fetchCars();
  }, []);

  const filteredCars = cars.filter(car =>
    car.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
    car.matricule.toLowerCase().includes(searchTerm.toLowerCase()) ||
    car.marque.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div className="text-center py-8">Chargement en cours...</div>;
  }

  if (error) {
    return (
      <div className="text-center py-8 text-red-500">
        <p>{error}</p>
        <button
          onClick={fetchCars}
          className="mt-2 bg-blue-500 text-white px-4 py-2 rounded"
        >
          Réessayer
        </button>
      </div>
    );
  }

  return (
    <>
      {/* Container pour les notifications */}
      <ToastContainer 
        position="top-right"
        autoClose={5000}
        hideProgressBar={false}
        newestOnTop={false}
        closeOnClick
        rtl={false}
        pauseOnFocusLoss
        draggable
        pauseOnHover
      />

      {/* Modal de confirmation */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-lg shadow-xl max-w-md w-full">
            <h3 className="text-lg font-bold mb-4">Confirmer la suppression</h3>
            <p className="mb-6">Êtes-vous sûr de vouloir supprimer cette voiture ? Cette action est irréversible.</p>
            <div className="flex justify-end gap-4">
              <button
                onClick={() => setShowModal(false)}
                className="px-4 py-2 bg-gray-300 hover:bg-gray-400 rounded transition"
              >
                Annuler
              </button>
              <button
                onClick={confirmDelete}
                className="px-4 py-2 bg-red-500 hover:bg-red-600 text-white rounded transition"
              >
                Confirmer
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Tableau des voitures */}
      <div className={`relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded ${
        color === "light" ? "bg-white" : "bg-lightBlue-900 text-white"
      }`}>
        <div className="rounded-t mb-0 px-4 py-3 border-0">
          <div className="flex flex-wrap items-center justify-between">
            <div className="relative px-4 max-w-full flex-grow flex-1">
              <h3 className={`font-semibold text-lg ${
                color === "light" ? "text-blueGray-700" : "text-white"
              }`}>
                Gestion des Voitures
              </h3>
            </div>
            <div className="flex items-center gap-4">
              <input
                type="text"
                placeholder="Rechercher..."
                className="px-3 py-1 border rounded focus:outline-none focus:ring-1 focus:ring-blue-500"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              <Link to="/admin/AddVoiture">
                <button className="bg-green-500 hover:bg-green-600 text-white font-semibold text-sm px-4 py-2 rounded shadow transition">
                  ➕ Ajouter
                </button>
              </Link>
            </div>
          </div>
        </div>

        <div className="block w-full overflow-x-auto">
          {filteredCars.length === 0 ? (
            <div className="text-center py-8">
              <p>Aucune voiture trouvée</p>
              {searchTerm && (
                <button
                  onClick={() => setSearchTerm("")}
                  className="mt-2 bg-gray-500 hover:bg-gray-600 text-white px-4 py-2 rounded transition"
                >
                  Réinitialiser la recherche
                </button>
              )}
            </div>
          ) : (
            <table className="items-center w-full bg-transparent border-collapse">
              <thead>
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Modèle</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Marque</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Matricule</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Prix/jour</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Disponible</th>
                  <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Ajoutée le</th>
                  <th className="px-6 py-3 text-center text-xs font-semibold uppercase">Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredCars.map((car) => (
                  <tr key={car._id} className="hover:bg-gray-50">
                    <td className="border-t-0 px-6 py-4 align-middle text-sm">{car.model}</td>
                    <td className="border-t-0 px-6 py-4 align-middle text-sm">{car.marque}</td>
                    <td className="border-t-0 px-6 py-4 align-middle text-sm font-medium">{car.matricule}</td>
                    <td className="border-t-0 px-6 py-4 align-middle text-sm">{car.prix_jour} €</td>
                    <td className="border-t-0 px-6 py-4 align-middle text-sm">
                      {car.disponible ? (
                        <span className="text-green-500">✅</span>
                      ) : (
                        <span className="text-red-500">❌</span>
                      )}
                    </td>
                    <td className="border-t-0 px-6 py-4 align-middle text-sm">
                      {moment(car.createdAt).format("DD/MM/YYYY")}
                    </td>
                    <td className="border-t-0 px-6 py-4 align-middle text-center">
                      <div className="flex items-center justify-center gap-2">
                        <Link to={{
                          pathname: `/admin/UpdateVoiture/${car._id}`,
                          state: { car }
                        }}>
                          <button className="bg-blue-500 hover:bg-blue-600 text-white text-xs font-semibold py-2 px-3 rounded shadow transition">
                            ✏️ Modifier
                          </button>
                        </Link>
                        <button
                          onClick={() => handleDeleteClick(car._id)}
                          className="bg-red-500 hover:bg-red-600 text-white text-xs font-semibold py-2 px-3 rounded shadow transition"
                        >
                          🗑️ Supprimer
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </>
  );
}

CardVoiture.defaultProps = {
  color: "light",
};

CardVoiture.propTypes = {
  color: PropTypes.oneOf(["light", "dark"]),
};
